body:
`moveField()` reorders by swapping neighbors in the original `fields` array, but the UI renders `groupedFields` sorted by `sortOrder` and grouped by `field.group`. This can cause move up/down to (a) swap with a field from a different group, (b) appear to do nothing when `sortOrder` is set (sorting immediately restores the previous visual order), and (c) behave inconsistently when search/type filtering is active. Consider implementing moves in terms of the currently displayed group order and persisting the change by updating `sortOrder` within the affected group (or by deriving display order purely from the array order and not additionally sorting by `sortOrder`).
```suggestion
      const movingField = fields.find((f) => f.id === id);
      if (!movingField) return;

      // Determine the logical group key (treat undefined group as a single ungrouped bucket)
      const groupKey = movingField.group ?? '__ungrouped__';

      // Use the currently visible fields to determine ordering within the group
      const visibleGroupFields = filteredFields.filter(
        (f) => (f.group ?? '__ungrouped__') === groupKey
      );

      const currentVisibleIndex = visibleGroupFields.findIndex((f) => f.id === id);
      if (currentVisibleIndex < 0) return;

      const targetVisibleIndex = direction === 'up' ? currentVisibleIndex - 1 : currentVisibleIndex + 1;
      if (targetVisibleIndex < 0 || targetVisibleIndex >= visibleGroupFields.length) return;

      const targetField = visibleGroupFields[targetVisibleIndex];

      const movingHasSortOrder = typeof movingField.sortOrder === 'number';
      const targetHasSortOrder = typeof targetField.sortOrder === 'number';

      // If either field participates in sortOrder-based ordering, swap their sortOrder values
      if (movingHasSortOrder || targetHasSortOrder) {
        const movingOrder = movingHasSortOrder ? (movingField.sortOrder as number) : 0;
        const targetOrder = targetHasSortOrder
          ? (targetField.sortOrder as number)
          : movingHasSortOrder
          ? direction === 'up'
            ? movingOrder - 1
            : movingOrder + 1
          : 0;

        const updated = fields.map((f) => {
          if (f.id === movingField.id) {
            return { ...f, sortOrder: targetOrder };
          }
          if (f.id === targetField.id) {
            return { ...f, sortOrder: movingOrder };
          }
          return f;
        });

        onFieldsChange?.(updated);
        return;
      }

      // Fallback: no sortOrder defined on either field; swap their positions in the fields array
      const movingIndex = fields.findIndex((f) => f.id === movingField.id);
      const targetIndex = fields.findIndex((f) => f.id === targetField.id);
      if (movingIndex < 0 || targetIndex < 0) return;

      const updated = [...fields];
      [updated[movingIndex], updated[targetIndex]] = [updated[targetIndex], updated[movingIndex]];
      onFieldsChange?.(updated);
    },
    [fields, filteredFields, onFieldsChange]
```
